    async def update_rule(
        self,
        id: str,
        body: UpdateRuleDto,
        *,
        options: RequestOptions | None = None,
    ) -> ForwardRuleResponseDto:
        """Update a URL forwarding rule

        Changes only the fields you send. The rule must still be on a domain you own; a rule on a domain you
        no longer own can only be deleted. Moving the rule to another host name follows the same ownership
        and one-rule-per-host rules as create. The resulting rule must be complete for its type: TEMPLATE
        needs a template, REDIRECT and IFRAME need a `targetUrl` (the current values count). A new
        `templateId` must be one of your templates, whatever the type.

        After the update a DNS check starts in the background. If you send `domainName`, the previous result
        is cleared (`dnsStatus` goes back to `pending`, `dnsLastOkAt` is cleared) before the new check. The
        response is written before that check, so it shows the status as it was.

        Body fields:
        - `domainName`: New host name. Same ownership rule as create. Sending it resets the DNS check to
          `pending`.
        - `forwardType`: Forwarding type. The rule must stay complete: TEMPLATE needs a template, REDIRECT
          and IFRAME need a `targetUrl`.
        - `templateId`: Your template ID. Changing `forwardType` to TEMPLATE checks that the template (this
          value or the stored one) is yours. Stored as null when the rule is not TEMPLATE.
        - `variables`: Template variables. Replaces the whole object. `domain` and `year` are set by LETO.
        - `targetUrl`: Target URL (http or https)
        - `redirectStatusCode`: Redirect status. 301 = permanent, 302 = temporary, 307 = temporary keeping
          the request method and body, 308 = permanent keeping the request method and body.
        - `preservePath`: REDIRECT only. When true, the request path is appended to the `targetUrl` path and
          the request query is added to the `targetUrl` query. Example: with `targetUrl`
          https://example.net/blog, a request for example.com/a?b=1 goes to https://example.net/blog/a?b=1.
        - `useSSL`: Serve the host over HTTPS
        - `enabled`: When false, the rule is kept but not served

        Errors (LetoApiError, branch on error_code):
        - 400: `BAD_REQUEST`: `id` is not a UUID, the rule would be incomplete for its type, `templateId` is
          not one of your templates, `targetUrl` is not an http/https URL, or `redirectStatusCode` is not
          301, 302, 307 or 308.
        - 403: `FORBIDDEN`: the current or new host name is not registered under your account.
        - 404: `NOT_FOUND`: no rule with this ID in your account.
        - 409: `CONFLICT`: a rule for the new host name already exists.

        HTTP: `PATCH /api/v1/forward/rules/{id}`

        Args:
            id: Forwarding rule ID (UUID)
            body: Request body (fields listed above).
            options: Retries and extra headers for this call.

        Returns:
            ForwardRuleResponseDto: The response body, as documented.

        Raises:
            LetoError: Any failure; LetoApiError when the API answered with an error.
        """
        response = await self._transport.request(
            "PATCH",
            "/api/v1/forward/rules/{id}",
            path_params={"id": id},
            body=body,
            options=options,
        )
        return cast(ForwardRuleResponseDto, response)

