    async def recheck_rule_dns(self, id: str, *, options: RequestOptions | None = None) -> AddonDnsStatusResponseDto:
        """Recheck the DNS of a forwarding rule

        Checks now whether the host name points to the LETO forwarding server and stores the result on the
        rule. If the last check was less than 30 seconds ago, or another check is running, no new check is
        made and the current status is returned with `checked: false`.

        Creating or changing a rule does not change DNS. Point the host name to the LETO forwarding server:
        for a subdomain (for example www.example.com) add a CNAME to `forward.leto.kr`; for the apex
        (example.com), which cannot hold a CNAME, use an ALIAS/ANAME or flattened CNAME to
        `forward.leto.kr`, or A/AAAA records with the addresses `forward.leto.kr` resolves to. The check
        passes when the CNAME chain reaches `forward.leto.kr`, or when every A/AAAA address of the host is a
        `forward.leto.kr` address (a mix of LETO and other addresses is `missing`).

        `dnsStatus` values: `pending` (not checked yet), `ok` (points to LETO), `missing` (no record or
        points elsewhere), `error` (lookup failed, no decision). It is informational only and never disables
        the rule. LETO rechecks every 6 hours while `ok` and every 15 minutes otherwise; an `ok` rule turns
        `missing` only after two misses in a row.

        Errors (LetoApiError, branch on error_code):
        - 400: `BAD_REQUEST`: `id` is not a valid UUID.
        - 404: `NOT_FOUND`: no rule with this ID in your account.

        HTTP: `POST /api/v1/forward/rules/{id}/dns-check`

        Args:
            id: Forwarding rule ID (UUID)
            options: Retries and extra headers for this call.

        Returns:
            AddonDnsStatusResponseDto: The response body, as documented.

        Raises:
            LetoError: Any failure; LetoApiError when the API answered with an error.
        """
        response = await self._transport.request(
            "POST",
            "/api/v1/forward/rules/{id}/dns-check",
            path_params={"id": id},
            options=options,
        )
        return cast(AddonDnsStatusResponseDto, response)

    async def list_templates(
        self,
        *,
        query: UrlForwardingListTemplatesQuery | None = None,
        options: RequestOptions | None = None,
    ) -> AsyncPage[ForwardTemplateDto, ForwardTemplatePageResponseDto]:
        """List forwarding page templates

        Returns the templates of your account, most recently created first, including `htmlContent`.

        Returns one page. Iterate `page.auto_paginate()` with `async for` to go over the items of every
        page.

        Query parameters:
        - `page`: Page number, starting at 1.
        - `size`: Items per page, 20 when omitted or invalid. There is no upper limit.
        - `sortBy`: Not used by this endpoint. Templates are always sorted by `updatedAt`, newest first.
        - `sortDirection`: Not used by this endpoint. Templates are always sorted by `updatedAt`, newest
          first.

        HTTP: `GET /api/v1/forward/templates`

        Args:
            query: Query parameters (listed above).
            options: Retries and extra headers for this call.

        Returns:
            AsyncPage[ForwardTemplateDto, ForwardTemplatePageResponseDto]: The first page; the response body
                is `page.body`.

        Raises:
            LetoError: Any failure; LetoApiError when the API answered with an error.
        """
        return await self._transport.request_page(
            "GET",
            "/api/v1/forward/templates",
            items_path=("data",),
            query=query,
            options=options,
        )

    async def create_template(
        self,
        body: CreateTemplateDto,
        *,
        options: RequestOptions | None = None,
    ) -> ForwardTemplateResponseDto:
        """Create a forwarding page template

        Creates an HTML template that TEMPLATE forwarding rules can serve (for example a parking page). Use
        `{{name}}` placeholders in `htmlContent` (spaces inside the braces are allowed). When a TEMPLATE
        rule is served, each placeholder is replaced with the HTML-escaped value from the rule `variables`.
        `{{domain}}` (the requested host name) and `{{year}}` (current year) are always filled by LETO and
        override rule variables of the same name. Placeholders without a value are removed. Template names
        are unique within your account.

        Body fields:
        - `name` (required): Template name, unique within your account
        - `description`: Free-form description (up to 1000 characters)
        - `htmlContent` (required): HTML body. `{{name}}` placeholders are filled from the rule variables;
          `{{domain}}` and `{{year}}` are always available.

        Errors (LetoApiError, branch on error_code):
        - 409: `CONFLICT`: you already have a template with this `name`.

        HTTP: `POST /api/v1/forward/templates`

        Args:
            body: Request body (fields listed above).
            options: Retries and extra headers for this call.

        Returns:
            ForwardTemplateResponseDto: The response body, as documented.

        Raises:
            LetoError: Any failure; LetoApiError when the API answered with an error.
        """
        response = await self._transport.request(
            "POST",
            "/api/v1/forward/templates",
            body=body,
            options=options,
        )
        return cast(ForwardTemplateResponseDto, response)

